INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-074', 'DEC', 'P1', 'OPEN', 'research-batch', 'observed_terms 97, 98 (DEFERRED); source_value_extractions parameter_id 4 and 5 rows from REF-00468', 'WHAT TERM NAMES THE WIDTH A PASSAGE NEEDS AT A TURN, AND WHICH PARAMETER HOLDS IT? OWNER DECISION. Found in sessions session_2026-11-06-pipeline-batch and session_2026-11-06-pipeline-batch-2 (PRs 211 and 212); the adversarial findings are in adversarial_findings, passes 8 and 9. The Anthropometry of Wheeled Mobility report (REF-00468) measures the width needed for a 90-degree turn, a 180-degree turn in a dead-end passage, and a 180-degree turn around an obstacle, and separately the diameter for a 360-degree turn. TERM-003 (turning circle, parameter 5) is defined as space for 360-degree rotation; TERM-002 (corridor width, parameter 4) is the clear width along a route. A width at a turn is neither. Adjudications 88/89 (observations 97 and 98) DEFERRED it under the owner''s rule that a new term''s definition is the owner''s (OT-2 pattern). The report''s turn-width rows are filed on parameter 4 with the setting stated; the 360-degree rows on parameter 5. CONSEQUENCE until decided: a determination on parameter 5 does not see the 180-degree width, which the report treats as an alternative basis for the minimum turning space and which the ADA says is covered by its 1525 mm turning space. OPTIONS: (a) a new term and parameter for width at a turn; (b) an expression of TERM-002 conditioned on a turn; (c) widen TERM-003. RESOLVE: owner defines the term; then adjudicate observations 97 and 98, and re-point rows by new rows (committed rows are immutable). DERIVE: select extraction_id, parameter_id, claimed_value, claimed_unit, setting from source_value_extractions where ref_id = ''REF-00468'' and parameter_id in (4, 5).', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-075', 'DEC', 'P1', 'OPEN', 'research-batch', 'evidence_sources REF-00468 tier/evidence_type; governance/tier-system.md line 15; schemas/tier_derivation.py TIER_MAP', 'CAN A CONTROLLED PRIMARY MEASUREMENT REPORT FILED AS grey REACH T1? OWNER DECISION. Found in sessions session_2026-11-06-pipeline-batch and session_2026-11-06-pipeline-batch-2 (PRs 211 and 212); the adversarial findings are in adversarial_findings, passes 8 and 9. REF-00468 is a federal contract research report (US Access Board contract, NIDRR grant), not peer reviewed, whose method is incremental mock-wall measurement of several hundred users. governance/tier-system.md line 15 lists T1 as ''clinical, occasionally grey for unpublished primary''. schemas/tier_derivation.py derives (grey, intrinsic) to tier 3 only, so the ladder''s own T1 wording is unreachable, and add-source refuses a tier that disagrees with the derivation (rule 8). The row is filed grey, tier 3, grey_flag 1; changing evidence_type to clinical to reach T1 would misstate what the source is. EFFECT: the largest measured dataset on wheelchair turning and passage widths renders as weak-band (circle) on every row. RESOLVE: owner rules either that the ladder stays (then this gap closes as decided, and the tier-system line is corrected by a DR) or that unpublished controlled primary research derives to T1 (then a tier_derivation change in a tooling PR, then amend-source on REF-00468 with the scope the ladder derives). DERIVE: select ref_id, tier, evidence_type, scope, grey_flag from evidence_sources where ref_id = ''REF-00468''; sed -n 15p governance/tier-system.md; grep -n grey schemas/tier_derivation.py.', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-076', 'DEC', 'P1', 'OPEN', 'research-batch', 'source_value_extractions.identity_code on rows from REF-00987, REF-00992, REF-01028, REF-01031, REF-01032, REF-00468', 'WHICH LENS DOES A CLAUSE CARRY WHEN ITS OWN TEXT NAMES NO ONE BUT SITS UNDER A DISABILITY HEADING (MOB OR ALL), AND WHO RE-KEYS THE ROWS ALREADY FILED INCONSISTENTLY? OWNER DECISION plus a writer gap. Found in sessions session_2026-11-06-pipeline-batch and session_2026-11-06-pipeline-batch-2 (PRs 211 and 212); the adversarial findings are in adversarial_findings, passes 8 and 9. Lens is the reader''s filing at extraction and judgment owns the crossing (CLAUDE.md section 6), but nothing rules the filing convention. Within one code the rows differ: the Korean annex items 6 and 7 are headed as for persons with disabilities and rows 207 to 210 are ALL while row 215 and every prior row of that code are MOB; the ADA door, turning and route rows are MOB while its force row is ALL; the UK Table 2 door rows are ALL while its door-force rows are MOB. Same quantity, two lenses, on nothing in the texts; synthesis keys on the lens. No writer changes an identity_code (amend-extraction takes comparator, extraction_method, extraction_status, figure_role, root_ref_id, root_type only), and a second row duplicates the figure (rule 5 and GAP-048). Adversarial findings 147, 171, 172 are PROVISIONAL-DISPUTED for this. RESOLVE: (1) owner rules the convention (MOB where the clause or its heading names disabled people, else ALL, is the one the later rows used, and is a proposal, not a ruling); (2) a writer to re-key a lens with the replaced value recorded (SW gap), or judgment supersedes by new rows. DERIVE: select ref_id, identity_code, count(*) from source_value_extractions where ref_id in (''REF-00468'',''REF-00987'',''REF-00992'',''REF-01028'',''REF-01031'',''REF-01032'') group by 1, 2.', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-077', 'DEC', 'P2', 'OPEN', 'research-batch', 'source_value_extractions.jurisdiction on REF-00992 rows; governance/jurisdiction-philosophy.md section 3.3', 'SHOULD AN INSTRUMENT FOR ENGLAND ONLY BE REPRESENTABLE BELOW UK? OWNER VOCABULARY DECISION. Found in sessions session_2026-11-06-pipeline-batch and session_2026-11-06-pipeline-batch-2 (PRs 211 and 212); the adversarial findings are in adversarial_findings, passes 8 and 9. UK Approved Document M volume 2 (REF-00992) says on its first pages that it is for use in England. Rows from it carry jurisdiction UK, the only spelling jurisdiction-philosophy.md section 3.3 allows, which has no sub-national code. Scotland, Wales and Northern Ireland have their own accessibility regulations, so a UK row reads as a claim about all four. Adversarial finding 160 (WITHHELD-FOR-OWNER). RESOLVE: owner rules whether a sub-national code or a scope note is wanted; if yes, a vocabulary change in a tooling PR, then a re-filing of REF-00992 rows by new rows. DERIVE: select count(*) from source_value_extractions where ref_id = ''REF-00992'' and jurisdiction = ''UK''; grep -n ''For use in England'' retrieval-log/session_2026-10-30-rest-landing-parameter/0e5d4dee25b341f4-full-text.txt.', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-078', 'EG', 'P1', 'OPEN', 'research-batch', 'source_value_extractions parameter_id 7 and 10; base_parameters 7 (TERM-007 reverberation time), 10 (TERM-024 colour temperature)', 'PARAMETERS 7 AND 10 HOLD NO EXTRACTION AFTER FOUR SOURCES WERE READ AGAINST THE WHOLE CATALOGUE, AND PARAMETERS 5 AND 8 REST ON FEW. Found in sessions session_2026-11-06-pipeline-batch and session_2026-11-06-pipeline-batch-2 (PRs 211 and 212); the adversarial findings are in adversarial_findings, passes 8 and 9. Neither of the code sources, the Spanish order, the Korean annex, the Portuguese pages nor the Anthropometry report holds a reverberation time or colour temperature figure (their scans say so, with the sweeps used). Room acoustics and lighting codes are not among the held sources. The parameters exist, with no direction set, so a batch that reads a room-acoustics or lighting code is the only way they get a row. Parameter 8 (LRV contrast) has one numeric source (UK Approved Document M para 0.26) and two absence rows. RESOLVE: a research batch aimed at room acoustic and lighting standards (for example the Irish TGD, DIN 18041, BS 8300, EN 12464), logged search first. DERIVE: select parameter_id, count(*), count(distinct ref_id) from source_value_extractions group by 1.', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-079', 'EG', 'P1', 'OPEN', 'research-batch', 'search_executions 198, 201; research_contract R1 (Co-1 pass)', 'NO CO-1 SOURCE HAS BEEN RETRIEVED FOR DOOR, CORRIDOR OR TURNING-SPACE DIMENSIONS. R1 PASSES ONLY BECAUSE A SEARCH WAS TARGETED AT CO-1. Found in sessions session_2026-11-06-pipeline-batch and session_2026-11-06-pipeline-batch-2 (PRs 211 and 212); the adversarial findings are in adversarial_findings, passes 8 and 9. Execution 198 (PubMed, three AND-ed concept groups) and execution 201 (a web search in long natural language) were aimed at disabled-persons-organisation or lived-experience dimension guidance and returned none; 198 was a query-shape failure (its diagnosis was corrected after execution 200 returned on-topic work), 201 returned code and housing-authority pages and itself said a targeted search was needed. The DoD R1 line reads PASS on a targeted search with no source. RESOLVE: a targeted retrieval at Disability Rights UK, Scope, the Centre for Accessible Environments, the Centre for Excellence in Universal Design, Disabled People''s Organisations International and national wheelchair-user organisations, with the Co-1 provenance rules of governance/co1-operational.md; log each query first. DERIVE: select exec_id, target_evidence_type, results_admitted from search_executions where target_evidence_type = ''co1'' and created_by_session like ''session_2026-11-06%''.', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-080', 'RP', 'P2', 'OPEN', 'research-batch', 'search_candidates 150 to 155; source_locators REF-00044, REF-00784, REF-00972, REF-00982, REF-00059, REF-00192', 'SIX PRIMARY-STUDY CANDIDATES ARE STAGED ON ABSTRACTS AND NONE HAS A REACHABLE FULL TEXT; THE CROSS-FILING ID OF ONE IS UNSETTLED. Found in sessions session_2026-11-06-pipeline-batch and session_2026-11-06-pipeline-batch-2 (PRs 211 and 212); the adversarial findings are in adversarial_findings, passes 8 and 9. Candidates 150 (Koontz 2010), 151 (Steinfeld 2010 review), 152 (King 2011), 153 (Higuchi 2009), 154 (Paquet 2012), 155 (Savelsbergh 1998) are PENDING-VERIFICATION. Europe PMC reports no open full text for Koontz and Steinfeld; the others were not tried. Admission cross-files to the stash ids where the DOI is held: REF-00784 (Koontz), REF-00972 (King), REF-00982 (Paquet), all RETIRED. Candidate 151''s DOI (10.1080/10400430903520280, PubMed) sits on two unrelated pre-reset stash rows (REF-00059, REF-00192: the GAP-008 shuffled-DOI defect), while REF-00044 carries the review''s exact title with a different DOI (10.1080/10400430903496580); which DOI is right is unverified. Tier guesses are 3 for Koontz, King, Higuchi, Paquet and Savelsbergh and 2 for Steinfeld, corrected after the pass; Koontz and Steinfeld share an author (Feathers), so an admission of both needs an independence check against full text. Koontz states, in its abstract, that between 10% and 100% of users could not manoeuvre in spaces meeting the US guideline (harm, R7). RESOLVE: obtain full texts through a library route (owner), then admit each through the pipeline, reusing the stash id; settle REF-00044 against Crossref first. DERIVE: select candidate_id, title, disposition from search_candidates where candidate_id between 150 and 155.', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-081', 'RP', 'P2', 'OPEN', 'research-batch', 'citation_mining for REF-00468; evidence_sources.citation_mining_status', 'CITATION MINING OF THE ANTHROPOMETRY REPORT IS DEFERRED IN BOTH DIRECTIONS. Found in sessions session_2026-11-06-pipeline-batch and session_2026-11-06-pipeline-batch-2 (PRs 211 and 212); the adversarial findings are in adversarial_findings, passes 8 and 9. R2 obliges mining of a tier 1 to 3 anchor. The report (REF-00468) cites the Canadian UDI wheelchair study and the BS 8300 research it compares against, and the 2010 follow-ups. Its bibliography begins at PDF page 170 (report page 159), not 159 as the deferral note says; evidence_sources.pages is the PDF count (173) against a report pagination that ends at 162. Forward mining needs a citation index not queried. The deferral is assigned to the next batch by the GAP-025 mechanism. RESOLVE: run a backward pass over the persisted bibliography and a forward pass, log both with log-mining --notes. DERIVE: select slug, local_ref_id, backward, forward, deferred_reason from citation_mining where local_ref_id = ''AWM-01''.', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-082', 'RP', 'P2', 'OPEN', 'research-batch', 'source_value_extractions for REF-00468, REF-01028, REF-01031, REF-01032, REF-00992, REF-00987; observed_terms for REF-00468', 'FIGURES STATED IN THE SOURCES READ AND LEFT UNFILED, AND CONCEPTS THE REPORT NAMES THAT NO OBSERVATION RECORDS. Found in sessions session_2026-11-06-pipeline-batch and session_2026-11-06-pipeline-batch-2 (PRs 211 and 212); the adversarial findings are in adversarial_findings, passes 8 and 9. Left unfiled by choice or for want of a quotable sentence, each stated in a persisted payload: the Anthropometry report''s percentile tables (cell sequences with no row labels in the extracted text), its 210 cm width for 95 percent of scooter users at the 180-degree turn (the sentence straddles a page break), its clear floor area, knee and toe clearance, latch-side clearance and grip-force concepts (no observation was harvested for them); the Spanish order''s 1,50 m circles at play areas, lift cabins, tables, kiosks and fountains (arts 8, 27 and others), its articles 6, 7 and 14 free heights; the Korean annex''s lift-front 1.4 m by 1.4 m, the 0.9 m ramp-width relaxation, competition-wheelchair figures (1.2 m door, 1.5 m by 1.5 m turning) and 1.5 m by 1.5 m passing zones; the Portuguese lift door 0,8 m and ramp exceptions; the UK 1500 by 1500 mm landing (2.7(d)) and manoeuvring space (3.28(a)), not filed on parameter 5 because the text calls them a landing and a manoeuvring space; the ADA passing spaces (403.5.3). RESOLVE: a catalogue re-reading with a derived figure inventory (see the SW gap on the scan procedure), then rows or declinations. DERIVE: the scan notes of source_scans for these refs list each one: select ref_id, notes from source_scans where created_by_session like ''session_2026-11-06%''.', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-083', 'EG', 'P2', 'OPEN', 'research-batch', 'source_scans; REF-01032 held text; REF-01026', 'THE PORTUGUESE DECREE IS HELD AS 5 OF 20 PAGES, AND ITS TURNING DIMENSION IS NOT AMONG THEM. Found in sessions session_2026-11-06-pipeline-batch and session_2026-11-06-pipeline-batch-2 (PRs 211 and 212); the adversarial findings are in adversarial_findings, passes 8 and 9. REF-01032 (Decreto-Lei 163/2006) text covers pages 1, 2, 9, 10 and 20 of 20. Items 2.2.1, 2.2.2 and 2.3.3 require a manoeuvre zone for a 360-degree rotation but the dimension sits in section 4.4, which is not held, so parameter 5 has no Portuguese row. REF-01026 is an unverified duplicate of the same decree. Parameters 7, 8, 10 and 11 are NOT examined for it. RESOLVE: retrieve the whole Diario da Republica issue (the persisted retrieval was partial), derive its full text with scripts/research/full_text.py, re-read; supersede or verify REF-01026. DERIVE: select ref_id, text_scope, pages_read, pages_total from source_scans where ref_id in (''REF-01032'',''REF-01026'').', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-084', 'EG', 'P3', 'OPEN', 'research-batch', 'source_value_extractions parameter_id 4, 5 for REF-00992 and REF-00987; BS 8300 not held', 'WHETHER THE UK 1500 BY 1500 mm LANDING AND MANOEUVRING SPACES ARE TURNING SPACES IS NOT SETTLED BY ANY HELD SOURCE. Found in sessions session_2026-11-06-pipeline-batch and session_2026-11-06-pipeline-batch-2 (PRs 211 and 212); the adversarial findings are in adversarial_findings, passes 8 and 9. UK Approved Document M volume 2 states 1500 x 1500 mm for the level landing before an entrance (2.7(d)) and the manoeuvring space before a lifting device (3.28(a)), and refers detail to BS 8300, which is not held. The wheelchair turning space of its sanitary guidance is carried by a diagram that was not read. Parameter 5 therefore has US (ADA 304.3.1, 1525 mm), Singapore, Spanish, Korean and report rows and no UK row. RESOLVE: obtain BS 8300 text, or read the diagrams of Approved Document M as page images (scripts/research/page_image.py), then file or decline. DERIVE: select jurisdiction, claimed_value, claimed_unit from source_value_extractions where parameter_id = 5 order by jurisdiction.', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-085', 'AUDT', 'P2', 'OPEN', 'research-batch', 'source_scans; research_batch_dod.py R16-scan; catalogue open pass', 'EVERY READING RECORDED IN THESE TWO BATCHES IS pre-screen; NO SOURCE WAS READ END TO END AND NO OPEN PASS WAS DONE. Found in sessions session_2026-11-06-pipeline-batch and session_2026-11-06-pipeline-batch-2 (PRs 211 and 212); the adversarial findings are in adversarial_findings, passes 8 and 9. All scan rows are method pre-screen with open_pass_done 0: located by keyword and clause number, a handful of pages read in full each. Each batch''s first scans then asserted absences that the critic disproved from the same payloads (door width and operating force in the Anthropometry report; a 22 N control force on a held Portuguese page; headroom and turning values in the UK text), so every ''no value found'' sentence in a pre-screen scan note is unverified. The rows and notes now carry the corrections, but the same sources have not been read in full. RESOLVE: full-read scans with the open pass (quantities the catalogue lacks) for REF-00468, REF-00992, REF-00987, REF-01028, REF-01031; treat any absence statement in an existing scan note as a lead. DERIVE: select ref_id, method, open_pass_done, count(*) from source_scans group by 1, 2, 3.', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-086', 'SW', 'P1', 'OPEN', 'governance', 'scripts/audit/research_batch_dod.py', 'THE DEFINITION-OF-DONE GATE READS NEITHER source_scans NOR source_value_extractions, SO COMPLIANT SAYS NOTHING ABOUT THE EXTRACTION ROWS. TOOLING PR (rule 10). Found in sessions session_2026-11-06-pipeline-batch and session_2026-11-06-pipeline-batch-2 (PRs 211 and 212); the adversarial findings are in adversarial_findings, passes 8 and 9. Re-run research_batch_dod.py --session on either session: R5 and R11 print EXAMINED: 0, R16-scan examines one admission, and no rule reads the extraction or scan tables, so the figures a determination rests on are checked only by db.py''s write-time verbatim test (which cannot see a column assignment, a locator, a unit or a role). Adversarial findings 153 and 166. RESOLVE: add the smallest rules that bind to a falsifiable property of those rows: claim_text verbatim against the persisted artefact at gate time; loc_note and source_section present; unit in the parameter''s family; a condition row has its edge; and an absence statement in a scan note cites its sweep. Each must print EXAMINED and fail on a seeded defect (selftest). DERIVE: python3 scripts/audit/research_batch_dod.py --session session_2026-11-06-pipeline-batch-2 | grep -c ''EXAMINED: 0''.', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-087', 'SW', 'P1', 'OPEN', 'governance', 'scripts/db.py amend-extraction, amend-search, resolve-candidate, record-scan; source_value_extractions columns identity_code, icf_code, needs_code, medical_code, contested, source_section, setting, loc_*; search_candidates harm_finding, title', 'NO SANCTIONED WRITER CORRECTS A LENS, A LOCATOR, A SETTING, THE contested FLAG, A CANDIDATE''S harm_finding OR TITLE, OR A SCAN NOTE. TOOLING PR (rule 10). Found in sessions session_2026-11-06-pipeline-batch and session_2026-11-06-pipeline-batch-2 (PRs 211 and 212); the adversarial findings are in adversarial_findings, passes 8 and 9. amend-extraction takes comparator, extraction_method, extraction_status, figure_role, root_ref_id and root_type; given a same-value it only appends the reason to notes. So a wrong locator (extraction 211: item 8 for item 13), a wrong setting (193: whole sample of 495, the task sample is 339), an inconsistent lens (see the lens DEC gap) and an unraised contested on the ADA 1525 mm rows (183, 193) can only be corrected in notes, and a corrected scan is a new scan row. amend-search raises harm_finding on a search but nothing raises it on a candidate (150 carries harm 0 beside search 197 raised). Candidate 151''s title reads D Souza for D''Souza. RESOLVE: one writer, ''correct-extraction'', that rewrites a named non-key column recording the replaced value (as amend-source does), and amend verbs for candidate harm_finding and title. DERIVE: python3 scripts/db.py amend-extraction --help | grep -A1 -- --field.', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-088', 'SW', 'P2', 'OPEN', 'governance', 'scripts/db.py log-search --result-artefact, amend-search --add-result-artefact; scripts/research/retrieval_log.py; I5 search_log_completeness', 'A RESULT PAYLOAD CAN BE LINKED TO A SEARCH ONLY IF THE SEARCH''S query_text NAMES THE PAYLOAD''S HOST, AND A WebSearch LEAVES NO PAYLOAD AT ALL. TOOLING PR (rule 10). Found in sessions session_2026-11-06-pipeline-batch and session_2026-11-06-pipeline-batch-2 (PRs 211 and 212); the adversarial findings are in adversarial_findings, passes 8 and 9. Europe PMC checks that support ''no open full text'' (persisted as 198b3da3fb3d7b6a.json, c4c1f76df9877588.json) cannot be linked to the PubMed search they support, and the corada pages and the Anthropometry PDF could be linked to the lookups only after the query text was suffixed with the URL (executions 203 and 202 carry or lack that). The result list of a WebSearch exists only in the transcript; the three web searches here were logged with notes written from it and the critic had to rebuild the lists from main.jsonl (the first search''s link count was mis-stated and corrected). This is the WebFetch problem of GAP-034 for the search tool. RESOLVE: let a result artefact link on the artefact''s own manifest purpose or ref_id, and persist a WebSearch result list as a retrieval-log artefact (the hook has it). DERIVE: select exec_id, query_text from search_executions where engine = ''web'' and created_by_session = ''session_2026-11-06-pipeline-batch-2''; grep -c europepmc retrieval-log/session_2026-11-06-pipeline-batch/manifest.jsonl.', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-089', 'SW', 'P2', 'OPEN', 'governance', 'scripts/db.py record-scan source_scans.pages_read, text_scope', 'pages_read ON A SCAN ROW COUNTS THE PAGES HELD, NOT THE PAGES READ, SO A POINTER SCAN READS AS A FULL READ. TOOLING PR (rule 10). Found in sessions session_2026-11-06-pipeline-batch and session_2026-11-06-pipeline-batch-2 (PRs 211 and 212); the adversarial findings are in adversarial_findings, passes 8 and 9. record-scan computes pages_read against pages_total from the text file; it cannot record that 19 of 173 pages were read in full. The row for REF-00468 shows 173 of 173 beside a note saying about twenty. Scan notes cannot be amended, so each correction is a new scan row for the same source and mode (several now exist per source). RESOLVE: a pages-read-in-full field set by the operator and checked against the page markers of the quotes the rows use; and an amend-scan verb that appends a dated correction as amend-search does. DERIVE: select ref_id, pages_read, pages_total, method, substr(notes, 1, 80) from source_scans where created_by_session like ''session_2026-11-06%''.', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-090', 'SW', 'P2', 'OPEN', 'governance', 'scripts/db.py _require_verbatim; scripts/research/retrieval_log.py normalise_quote', 'THE VERBATIM CHECK CANNOT QUOTE A KOREAN SENTENCE THAT CROSSES A LINE BREAK, SO claim_text IS CUT MID-WORD. TOOLING PR (rule 10). Found in sessions session_2026-11-06-pipeline-batch and session_2026-11-06-pipeline-batch-2 (PRs 211 and 212); the adversarial findings are in adversarial_findings, passes 8 and 9. A PDF-extracted Korean line break can fall inside a word or between a stem and its ending; whitespace normalisation turns it into a space the source does not have. Extraction 215 quotes a sentence that stops at the break (...1.2미터 이상으) and extraction 209 starts at one (에는 1.5미터...), so their claim_text is a fragment and, for 209, drops its own condition (carried by the edge quote instead). Same class as GAP-056 (CJK numerals). RESOLVE: for CJK text compare with all whitespace removed, then store the quote as written. DERIVE: select extraction_id, claim_text from source_value_extractions where ref_id = ''REF-01031'' and extraction_id in (209, 215).', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-091', 'SW', 'P2', 'OPEN', 'governance', 'scripts/db.py log-search --origin; adversarial_passes', 'A SEARCH RUN BECAUSE A CRITIC FOUND A QUERY-SHAPE FAILURE CANNOT BE LABELLED adversarial-pass AT WRITE TIME. TOOLING PR (rule 10). Found in sessions session_2026-11-06-pipeline-batch and session_2026-11-06-pipeline-batch-2 (PRs 211 and 212); the adversarial findings are in adversarial_findings, passes 8 and 9. log-search --origin adversarial-pass requires --origin-pass-id, and the pass row exists only after record-adversarial-pass, which needs the critic''s transcript committed, which comes after the searches. --origin incidental refuses any target flag. Executions 199 and 200 were therefore logged incidental without targets, which removes them from the coverage counts they belong to. RESOLVE: accept a deferred pass id (backfilled by amend-search --set-origin-pass-id, which already exists NULL to value) and allow targets with origin adversarial-pass. DERIVE: select exec_id, origin, target_tier from search_executions where exec_id in (199, 200).', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-092', 'SW', 'P2', 'OPEN', 'governance', 'the scan procedure (scripts/research/full_text.py, record-scan, db.py coverage); .claude/commands', 'A CATALOGUE READING DEPENDS ON THE READER''S KEYWORDS, AND THEY MISSED STATED FIGURES IN BOTH BATCHES. PROCESS AND TOOLING. Found in sessions session_2026-11-06-pipeline-batch and session_2026-11-06-pipeline-batch-2 (PRs 211 and 212); the adversarial findings are in adversarial_findings, passes 8 and 9. Twice running, the pre-screen of a persisted text keyed on the words the reader expected (anchura libre, headroom, 2000 mm, 1500 mm x 1500) and missed the same quantity in another spelling (ancho de paso libre, 2.1m, 1500mm x 1500mm, 22 N on a page the note said was not examined). Every absence note was then false and had to be found by a second reader. The sources are text; the number-and-unit statements in them can be inventoried mechanically per page. RESOLVE: a derived figure inventory (every number with a unit or a ratio, with its page and surrounding sentence) printed beside the parameter list for a catalogue reading, so an absence claim is checked against the inventory instead of a keyword; and an absence statement in a scan note must cite the sweep. This replaces nothing and adds one reader (rule 8 and the net-negative rule apply: name what it reads). DERIVE: compare the first and second scan notes for REF-00468, REF-01032 and REF-01028 in source_scans.', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-093', 'SW', 'P3', 'OPEN', 'governance', 'scripts/db.py update_locator', 'update-locator REWRITES created_by_session AND created_at ON A STASH ROW ALTHOUGH ITS DOCSTRING SAYS ONLY THE STATUS MOVES. TOOLING PR (rule 10). Found in sessions session_2026-11-06-pipeline-batch and session_2026-11-06-pipeline-batch-2 (PRs 211 and 212); the adversarial findings are in adversarial_findings, passes 8 and 9. Marking the REF-00468 lead PROMOTED set the row''s created_by_session to the batch session and created_at to today, on a row whose notes say it was migrated on 2026-08-23. The code comments call this ''who worked this lead'' by design; the docstring and the column names say otherwise, so a reader will take the row for one created in this batch. Adversarial finding 178 of the first pass notes it. RESOLVE: add updated_by_session / updated_at to source_locators, or stop rewriting the created_* pair. DERIVE: select ref_id, status, created_by_session, created_at, notes from source_locators where ref_id = ''REF-00468''.', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-094', 'ST', 'P2', 'OPEN', 'research-batch', 'scripts/assess/assess_cell.py NOTATION_FAMILIES; source_value_extractions.claimed_unit on parameters 4, 6, 9, 11', 'ROWS IN METRES, CENTIMETRES, MILLIMETRES AND NEWTONS ARE FILED BESIDE ONE ANOTHER ON PARAMETERS 4, 6, 9 AND 11, AND THE ENGINE OWNS NO LENGTH OR FORCE FAMILY. See GAP-072, which this extends. Found in sessions session_2026-11-06-pipeline-batch and session_2026-11-06-pipeline-batch-2 (PRs 211 and 212); the adversarial findings are in adversarial_findings, passes 8 and 9. Each row keeps the unit its source states (1,80 m, 80 cm, 915 mm, 22.2 N, 5 lbf given with its newton equivalent), so compose_value over any of these parameters returns NULL with ''stated in different units'' as soon as two sources differ, exactly as on parameter 12. Only the gradient family exists. RESOLVE: add a length family (m, cm, mm) and a force family (N), derived from the unit table not listed in code; then re-run the determination for parameters 4, 6, 9, 11. DERIVE: select parameter_id, claimed_unit, count(*) from source_value_extractions where parameter_id in (4, 6, 9, 11) group by 1, 2.', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-095', 'AUDT', 'P2', 'OPEN', 'governance', 'scripts/preflight.sh output; test_scan_contract G01 and G02; scan_debt, validate_schema_cross_check, retired_vocabulary, research_dod, research_protocol_audit, metadata_integrity_audit', 'PREFLIGHT PRINTS ADVISORY FAILURES THAT NO SESSION HAS DIAGNOSED, AND TWO TESTS ARE RED ON UNTOUCHED main. Found in sessions session_2026-11-06-pipeline-batch and session_2026-11-06-pipeline-batch-2 (PRs 211 and 212); the adversarial findings are in adversarial_findings, passes 8 and 9. scripts/tests/test_scan_contract.py cases G01 (R16-scan grandfathers an old batch and fails a new admission with no catalogue reading) and G02 (a targeted reading does not discharge R16-scan) fail on origin/main as well as here (checked in a worktree of origin/main). The other six advisory checks print FAIL on this branch in both PRs; they were not run against origin/main, so whether any is new is UNVERIFIED. An advisory failure that is always red teaches the reader to ignore all of them. RESOLVE: run each on a worktree of origin/main, record which are red there, fix or retire each (deletion needs only evidence, CLAUDE.md section 8). DERIVE: scripts/preflight.sh 2>&1 | grep -E ''^\[FAIL\]''; python3 scripts/tests/test_scan_contract.py | grep -E ''\[✗\]''.', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-096', 'AUDT', 'P3', 'OPEN', 'governance', 'sessions/session_2026-10-30-ramp-spec-pages-rebuild.md section 2; adversarial_passes pass_id 7', 'ADVERSARIAL PASS 7 IS STILL OPEN, AND ITS CLOSING NEEDS THE OWNER OR A TOOLING CHANGE. Carried from the previous session so that it is on the registry; not caused by these batches. close-adversarial-pass refuses pass 7 because finding 140 names a migration path the rebuild deleted. RESOLVE: owner decides whether to dispose finding 140 OWNER-RULED or a tool allows a deleted-artefact disposition; then close. DERIVE: select pass_id, closed_at from adversarial_passes where closed_at is null.', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 05:04', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL, NULL);
